data_path = 'e:\SHARE\Fe\Data\analysis\06_fit_with_J0';
if ~exist('fit_resEi400','var')
    ld = load(fullfile(data_path,'FitEn_cut400_1DfExp3Cuts_from_base_dirGH_dE20_fix_bg_slope.mat'));
    fit_resEi400 = ld.fit_res;
end
if ~exist('cuts2fit400','var')
    ld = load('multicuts_fit_dataGH_ei400meVse.mat');
    cuts2fit400 = ld.cuts2fit400;
end
cuts2fit = cuts2fit400;
fit_res = fit_resEi400;
mi = maps_instrument(400,600,'S');
sample=IX_sample(true,[1,0,0],[0,1,0],'cuboid',[0.04,0.03,0.02]);
for i=1:numel(cuts2fit.cutsS_list)
    cuts2fit.cutsS_list{i} = cuts2fit.cutsS_list{i}.set_instrument(mi);
    cuts2fit.cutsS_list{i} = cuts2fit.cutsS_list{i}.set_sample(sample);
end

%%
acolor r
Sgnl = fit_res.S;  
pd(Sgnl);ly 0 3;liny;keep_figure %[output:65f4c92a]
J0 = fit_res.J0;
pd(J0);ly 20 60;keep_figure %[output:42ca3381]
G = fit_res.gamma;
G.s_axis.units = 'meV';
pd(G);ly 0 250;keep_figure %[output:34a4596b]

dE = min(Sgnl.x(2:end)-Sgnl.x(1:end-1)) %[output:29450cc9]
e_min = Sgnl.x(1);

%%
En = 100 %[output:54d84848]
dE_step = 4; %original energy transfer step data were binned to. No point in going finer
half_dE = 10;
en_idx =  floor((En-e_min)/dE)+1;
the2Dcuts = cuts2fit.cutsS_list;%(1:2);
init_fg_params = fit_res.all_fit_par(en_idx).p;
init_bg_params = fit_res.all_fit_par(en_idx).bp;
%init_bg_params = cellfun(@(par)[par(1),par(3)],init_bg_params,'UniformOutput',false);
[fit_obj,fit_par,figa,figb]=fit_single_set(the2Dcuts,En,half_dE,dE_step,init_fg_params,init_bg_params,false) %[output:2fcd14ef] %[output:4786df16] %[output:8890a081] %[output:5ff3b6c9] %[output:6e64e718] %[output:59885c40] %[output:87dbdb7d]
wsEn100Ei400 = src(figb);
%%
%fit_res.all_fit_par(en_idx) = fit_par;
acolor r
plot(fit_res.S);ly 0 4;liny;
acolor g
Sgnl.signal(en_idx) = fit_par.p(4);
pd(Sgnl);ly 0 4;liny;keep_figure

acolor r
plot(fit_res.J0);ly 0 100;liny;
acolor g
J0.signal(en_idx) = fit_par.p(6);
pd(J0);ly 0 100;keep_figure

acolor r
plot(fit_res.gamma);ly 0 300;liny;
acolor g
G.signal(en_idx) = fit_par.p(3);
pd(G);ly 0 300;keep_figure


